    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.16,2.0],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.1,1.7],
    [240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.3/P[2],2.3],
    [120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.84/P[3],1.5],
    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.77/P[4],2.6],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,1.17/P[5],1.9]
