  const cell=Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const lH=24,lIdx=Math.min((y/lH)|0,9),lY=y%lH;
  const lAct=Math.sin(lIdx*P[6]/17*Math.PI+t*P[4]/11)*0.5+0.5;
  const lEdge=(lY<1||lY>lH-2)?lAct*0.4:0;
  const gX=(x%40<1)?0.15:0,gY=(y%lH<1)?0.2:0;
  const barR=x<110&&lY<9;
  const bV=Math.sin(t*P[lIdx%10]*0.15+lIdx*1.3)*0.5+0.5;
  const bFill=barR&&(x<8+bV*95)?bV*0.6:0;
